//! Pre-final base-vars lexical utility. Physical rows stream and retire; only
//! actual declarations and provisional spool bytes persist until final Inputs.
use super::*;
use std::{cell::RefCell,io::{self,Write},path::{Path,PathBuf}};
use dm_preprocess::source_arena_credit::{SourceArenaCredit,SourceArenaWork};
use crate::request_runner::utility_capture::{Capture,Roster};
use crate::input_snapshot::utility_capture::UtilityPhysicalInputs;
use dq_analyze::key_policy_control::Control;
fn invalid(message:&'static str)->io::Error{io::Error::new(io::ErrorKind::InvalidInput,message)}
struct Work<'a>{work:&'a dyn SourceArenaWork,credit:&'a mut Option<SourceArenaCredit>,temporary:[usize;2]}
impl Control for Work<'_>{type Error=io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->io::Result<()>{self.work.checkpoint()}fn reserve(&mut self,n:usize)->io::Result<()>{match self.credit.as_mut(){Some(credit)=>self.work.grow(credit,n),None=>{*self.credit=Some(self.work.reserve(n)?);Ok(())}}}fn temporary(&mut self,slot:usize,n:usize)->io::Result<()>{let old=*self.temporary.get(slot).ok_or_else(||invalid("base-vars temporary slot absent"))?;if n>old{self.reserve(n-old)?;self.temporary[slot]=n;}Ok(())}fn overflow(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}}
struct PhysicalWork<'a,'b>{physical:&'a RefCell<&'b mut dyn UtilityPhysicalInputs>,credit:&'a mut Option<SourceArenaCredit>,temporary:[usize;2]}
impl Control for PhysicalWork<'_,'_>{type Error=io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->io::Result<()>{crate::daemon::control::checkpoint()}fn reserve(&mut self,n:usize)->io::Result<()>{let mut physical=self.physical.try_borrow_mut().map_err(|_|io::Error::from(io::ErrorKind::WouldBlock))?;physical.with_work(&mut|work|match self.credit.as_mut(){Some(credit)=>work.grow(credit,n),None=>{*self.credit=Some(work.reserve(n)?);Ok(())}})}fn temporary(&mut self,slot:usize,n:usize)->io::Result<()>{let old=*self.temporary.get(slot).ok_or_else(||invalid("base-vars temporary slot absent"))?;if n>old{self.reserve(n-old)?;self.temporary[slot]=n;}Ok(())}fn overflow(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}}
struct Text{text:String,_credit:SourceArenaCredit}
fn decode(bytes:&[u8],work:&dyn SourceArenaWork)->io::Result<Text>{work.checkpoint()?;let count=bytes.utf8_chunks().try_fold(0usize,|n,chunk|n.checked_add(chunk.valid().len()).and_then(|n|n.checked_add(if chunk.invalid().is_empty(){0}else{3}))).ok_or(io::ErrorKind::OutOfMemory)?;let bound=count.checked_mul(8).ok_or(io::ErrorKind::OutOfMemory)?;let credit=work.reserve(bound)?;let decoded=String::from_utf8_lossy(bytes);if let std::borrow::Cow::Owned(value)=&decoded{if value.capacity()>count.saturating_mul(4){return Err(io::ErrorKind::OutOfMemory.into())}}let text=decoded.replace("\r\n","\n");if text.capacity()>count.saturating_mul(4){return Err(io::ErrorKind::OutOfMemory.into())}drop(decoded);work.checkpoint()?;Ok(Text{text,_credit:credit})}
struct Files<'a,'b>{root:&'a Path,roster:&'a Roster,physical:&'a RefCell<&'b mut dyn UtilityPhysicalInputs>}
impl dq_analyze::captured_base_vars_dead::Files for Files<'_,'_>{fn visit(&mut self,consume:&mut dyn FnMut(&str,&str,bool)->io::Result<()>)->io::Result<()>{for path in self.roster.paths(){crate::daemon::control::checkpoint()?;let relative=path.strip_prefix(self.root).map_err(|_|invalid("base-vars actual path escaped root"))?;let raw={let mut physical=self.physical.try_borrow_mut().map_err(|_|io::Error::from(io::ErrorKind::WouldBlock))?;physical.read_optional(path,crate::runner_host::policy_capture::MAX_POLICY_CAPTURE_CHARGE)?};let Some(raw)=raw else{continue};let mut text=None;let mut relative_text=None;let mut path_credit=None;{let mut physical=self.physical.try_borrow_mut().map_err(|_|io::Error::from(io::ErrorKind::WouldBlock))?;physical.with_work(&mut|work|{let n=relative.as_os_str().len().checked_mul(16).ok_or(io::ErrorKind::OutOfMemory)?;path_credit=Some(work.reserve(n)?);let shown=relative.to_string_lossy().replace('\\',"/");if shown.capacity()>n{return Err(io::ErrorKind::OutOfMemory.into())}relative_text=Some(shown);text=Some(decode(raw.bytes(),work)?);Ok(())})?;}let text=text.ok_or_else(||invalid("base-vars decode was not visited"))?;let relative=relative_text.as_deref().ok_or_else(||invalid("base-vars relative path was not produced"))?;consume(relative,&text.text,relative.ends_with(".dmm"))?;drop(text);drop(relative_text);drop(path_credit);drop(raw);}Ok(())}}
pub(crate) struct BaseVarsCapture{root:PathBuf,cache:PathBuf,tsv:bool,few:bool,vars:Vec<dq_analyze::captured_base_vars_dead::Declaration>,stdout:Option<crate::selected_report_spool::Stage>,stderr:Option<crate::selected_report_spool::Stage>,ready:bool,credit:Option<SourceArenaCredit>}
impl BaseVarsCapture{
 pub(crate) fn new(root:PathBuf,cache:PathBuf,tsv:bool,few:bool)->Self{Self{root,cache,tsv,few,vars:Vec::new(),stdout:None,stderr:None,ready:false,credit:None}}
 pub(crate) fn take(&mut self)->io::Result<(crate::selected_report_spool::Verified,crate::selected_report_spool::Verified)>{if !self.ready{return Err(invalid("base-vars provisional result is unissued"))}self.ready=false;let out=self.stdout.take().ok_or_else(||invalid("base-vars actual stdout spool absent"))?.seal_allow_empty()?.validate(crate::request_runner::schema_capture::drain)?.0;let err=self.stderr.take().ok_or_else(||invalid("base-vars actual stderr spool absent"))?.seal_allow_empty()?.validate(crate::request_runner::schema_capture::drain)?.0;Ok((out,err))}
}
impl Capture for BaseVarsCapture{
 fn begin_attempt(&mut self){self.vars=Vec::new();self.stdout=None;self.stderr=None;self.ready=false;self.credit=None;}
 fn workspace_roster(&mut self,_:&crate::runner_host::workspace_discovery::DiscoveryReceipt,_:&dyn SourceArenaWork)->io::Result<()>{Ok(())} // separate actual codeDM/mapsDMM traversal below
 fn prepare_current(&mut self,_:&dm_tree::frontend::DiagnosticSourceView<'_>,snapshot:&crate::runner_host::query_snapshot::SourceSnapshot,_:&dyn SourceArenaWork)->Result<(),Box<dyn std::error::Error>>{snapshot.with_original_utility_model(crate::policy_request::WorkspaceAuxiliaryQuestion::BaseVars,false,|inputs,root,_budget,work,_body,_markers|{let mut control=Work{work,credit:&mut self.credit,temporary:[0;2]};self.vars=dq_analyze::captured_base_vars_dead::prepare(inputs,root,&mut control).map_err(|actual|match actual.downcast::<io::Error>(){Ok(actual)=>dq_analyze::captured_reactive_reads::Failure::Operational(*actual),Err(actual)=>dq_analyze::captured_reactive_reads::Failure::Unsupported(actual.to_string())})?;Ok(())})?;Ok(())}
 fn capture(&mut self,physical:&mut dyn UtilityPhysicalInputs)->io::Result<()>{let mut roster=None;physical.with_base_vars_roster(&self.root,&mut|actual,work|{roster=Some(Roster::capture(actual,work)?);Ok(())})?;let roster=roster.ok_or_else(||invalid("base-vars actual directory traversal did not complete"))?;let physical=RefCell::new(physical);let mut files=Files{root:&self.root,roster:&roster,physical:&physical};let mut work=PhysicalWork{physical:&physical,credit:&mut self.credit,temporary:[0;2]};let mut stdout=crate::selected_report_spool::Stage::new(&self.cache)?;let mut stderr=crate::selected_report_spool::Stage::new(&self.cache)?;dq_analyze::captured_base_vars_dead::render_prepared(&self.vars,&mut files,self.tsv,self.few,&mut work,|channel,args|match channel{dq_analyze::captured_base_vars_dead::OutputChannel::Stdout=>writeln!(stdout,"{args}"),dq_analyze::captured_base_vars_dead::OutputChannel::Stderr=>writeln!(stderr,"{args}")})?;drop(work);drop(files);drop(roster);self.vars=Vec::new();self.credit=None;self.stdout=Some(stdout);self.stderr=Some(stderr);self.ready=true;Ok(())}
}
